mapper.select:
SELECT tbt.id, tbt.time_block_id, tbt.title
FROM time_block_tasks tbt
JOIN time_blocks tb ON tb.id = tbt.time_block_id
WHERE tbt.id = #{id}
  AND tb.user_id = #{userId}

mapper.insert:
INSERT INTO time_block_tasks (time_block_id, title)
SELECT 
    #{timeBlockTask.timeBlockId},
    #{timeBlockTask.title}
WHERE EXISTS(
    SELECT 1
    FROM time_blocks tb
    WHERE tb.id = #{timeBlockTask.timeBlockId}
      AND tb.user_id = #{userId}
)

mapper.update:
UPDATE time_block_tasks
SET
    time_block_id = #{timeBlockTask.timeBlockId},
    title = #{timeBlockTask.title}
WHERE
    id = #{timeBlockTask.id}
  AND EXISTS(
    SELECT 1
    FROM time_blocks current_tb
    WHERE current_tb.id = time_block_tasks.time_block_id
      AND current_tb.user_id = #{userId}
  )
  AND EXISTS(
    SELECT 1
    FROM time_blocks new_tb
    WHERE new_tb.id = #{timeBlockTask.timeBlockId}
      AND new_tb.user_id = #{userId}
  )

mapper.delete:
DELETE FROM time_block_tasks 
WHERE id = #{id}
  AND EXISTS(
    SELECT 1
    FROM time_blocks tb
    WHERE tb.id = time_block_tasks.time_block_id
      AND tb.user_id = #{userId}
  )
